package handlers

import (
	"bytes"
	"encoding/json"
	"testing"
)

// TestContract_WebPayloads_Academy verifies that the exact JSON payloads generated by
// web/src/lib/api.ts decode into academy-service request structs under DisallowUnknownFields.
func TestContract_WebPayloads_Academy(t *testing.T) {
	t.Run("purchase-request payload decodes into CreatePurchaseRequestDTO", func(t *testing.T) {
		payload := []byte(`{
			"payment_method": "vodafone_cash",
			"transfer_reference": "TX123456",
			"sender_number": "01012345678",
			"amount": 150
		}`)
		var dto CreatePurchaseRequestDTO
		dec := json.NewDecoder(bytes.NewReader(payload))
		dec.DisallowUnknownFields()
		if err := dec.Decode(&dto); err != nil {
			t.Fatalf("failed to decode purchase request payload: %v", err)
		}
		if dto.PaymentMethod != "vodafone_cash" || dto.TransferReference != "TX123456" || dto.SenderNumber != "01012345678" || dto.Amount != 150 {
			t.Fatalf("unexpected fields in decoded CreatePurchaseRequestDTO: %+v", dto)
		}
	})

	t.Run("orders payload decodes into CreateOrderDTO", func(t *testing.T) {
		payload := []byte(`{
			"subject_ids": ["subj-1", "subj-2"],
			"payment_method": "instapay",
			"transfer_reference": "TX987654",
			"sender_number": "01012345678",
			"amount_paid": 300
		}`)
		var dto CreateOrderDTO
		dec := json.NewDecoder(bytes.NewReader(payload))
		dec.DisallowUnknownFields()
		if err := dec.Decode(&dto); err != nil {
			t.Fatalf("failed to decode orders payload: %v", err)
		}
		if len(dto.SubjectIDs) != 2 || dto.PaymentMethod != "instapay" || dto.TransferReference != "TX987654" || dto.SenderNumber != "01012345678" || dto.AmountPaid != 300 {
			t.Fatalf("unexpected fields in decoded CreateOrderDTO: %+v", dto)
		}
	})
}
